create extension if not exists pgcrypto;
create type public.user_role as enum ('sme','admin');
create type public.review_state as enum ('검토중','검토완료');
create table public.profiles(id uuid primary key references auth.users on delete cascade,email text not null,display_name text,company text,organization text,role user_role not null default 'sme',is_active boolean not null default true,last_login timestamptz);
create table public.jobs(id int primary key,job_group text not null,job_series text not null,name text not null,description text not null,mission text not null,companies text[] not null default '{}');
create table public.tasks(id text primary key,job_id int not null references jobs,sort_order int not null,name text not null,source_row int not null,unique(job_id,sort_order));
create table public.activities(id text primary key,task_id text not null references tasks,sort_order int not null,text text not null,source_row int not null);
create table public.skills(id text primary key,job_id int not null references jobs,name text not null,hard_soft text not null check(hard_soft in ('Hard','Soft')),ksao text not null,description text not null,related_task text,source_row int not null);
create table public.skill_pool(id bigserial primary key,job_id int not null references jobs,name text not null,source_row int not null);
create table public.job_assignments(user_id uuid references profiles,job_id int references jobs,primary key(user_id,job_id));
create table public.review_status(user_id uuid references profiles,job_id int references jobs,status review_state not null,updated_at timestamptz not null default now(),primary key(user_id,job_id));
create table public.feedbacks(id uuid primary key default gen_random_uuid(),user_id uuid not null references profiles,job_id int not null references jobs,feedback_type text not null check(feedback_type in ('description','mission','task','activity','skill','overall')),target_key text not null,original_text text not null default '',review_result text check(review_result in ('적정','수정 필요','삭제 검토','추가 필요')),comment text,updated_at timestamptz not null default now(),unique(user_id,job_id,feedback_type,target_key));
create table public.feedback_admin(feedback_id uuid primary key references feedbacks on delete cascade,status text not null default '미검토' check(status in ('미검토','검토중','반영','미반영','추가논의')),memo text,updated_at timestamptz not null default now());
create table public.notifications(id bigserial primary key,user_id uuid references profiles,type text not null,payload jsonb not null default '{}',read_at timestamptz,created_at timestamptz not null default now());
create or replace function public.is_admin() returns boolean language sql security definer set search_path=public stable as $$select exists(select 1 from profiles where id=auth.uid() and role='admin' and is_active)$$;
create or replace function public.is_active_user() returns boolean language sql security definer set search_path=public stable as $$select exists(select 1 from profiles where id=auth.uid() and is_active)$$;
alter table profiles enable row level security;alter table jobs enable row level security;alter table tasks enable row level security;alter table activities enable row level security;alter table skills enable row level security;alter table skill_pool enable row level security;alter table job_assignments enable row level security;alter table review_status enable row level security;alter table feedbacks enable row level security;alter table feedback_admin enable row level security;alter table notifications enable row level security;
create policy master_jobs_read on jobs for select using(is_active_user());create policy master_tasks_read on tasks for select using(is_active_user());create policy master_activities_read on activities for select using(is_active_user());create policy master_skills_read on skills for select using(is_active_user());create policy master_pool_read on skill_pool for select using(is_active_user());
create policy feedback_own_select on feedbacks for select using(user_id=auth.uid() or is_admin());create policy feedback_own_insert on feedbacks for insert with check(user_id=auth.uid() and is_active_user());create policy feedback_own_update on feedbacks for update using(user_id=auth.uid() and is_active_user());create policy feedback_own_delete on feedbacks for delete using(user_id=auth.uid() and is_active_user());
create policy profiles_read on profiles for select using(id=auth.uid() or is_admin());create policy profiles_update on profiles for update using(id=auth.uid() or is_admin());create policy feedback_admin_read on feedback_admin for select using(is_admin());create policy feedback_admin_write on feedback_admin for all using(is_admin()) with check(is_admin());create policy notifications_admin_read on notifications for select using(is_admin());create policy notifications_own_insert on notifications for insert with check(user_id=auth.uid() and is_active_user());
